pm.test("User has public fields and no password", () => { 
  const u = pm.response.json().user;
  pm.expect(u).to.include.all.keys("id","email","fullName","phone","country","city","street","postalCode","createdAt","updatedAt");
  pm.expect(u).to.not.have.property("password"); });

pm.test("auth_session cookie is set (HttpOnly, SameSite=Lax)", () => { 
  pm.expect(pm.cookies.has("auth_session")).to.be.true;
  const sc = [].concat(pm.response.headers.filter((h) => h.key.toLowerCase() === "set-cookie").map((h) => h.value)).join(";").toLowerCase();
  pm.expect(sc).to.include("httponly"); pm.expect(sc).to.include("samesite=lax"); });

