exec:
pm.test("Shipment has full schema", () => { 
  const sh = pm.response.json().shipment;
  pm.expect(sh).to.include.all.keys("id","trackingNumber","status","from","to","package","service","options","rate","createdAt","updatedAt");
  pm.expect(sh.id).to.be.a("number");
  pm.expect(sh.trackingNumber).to.match(/^TR\d{9}$/);
  pm.expect(sh.status).to.be.oneOf(["draft","finalized"]);
  ["from","to"].forEach((k) => pm.expect(sh[k]).to.have.all.keys("name","phone","country","city","street","postalCode"));
  pm.expect(sh.package).to.include.all.keys("weight","length","width","height","description");
  pm.expect(sh.service).to.include.all.keys("type","shipmentType","pickupMethod");
  pm.expect(sh.options).to.have.all.keys("signature","liquid","insurance","packaging");
  pm.expect(sh.rate).to.have.all.keys("base","total","signature","insurance","packaging","liquid");
  pm.expect(new Date(sh.createdAt).toString()).to.not.eql("Invalid Date"); });

